#include "MainEditor.h"
namespace cymbalforge { MainEditor::MainEditor(CymbalEngine& e):engine(e),surface(e) { title.setText("CYMBALFORGE  /  MODAL CYMBAL SYNTHESIS",juce::dontSendNotification); title.setJustificationType(juce::Justification::centred); status.setJustificationType(juce::Justification::centredRight); addAndMakeVisible(title); addAndMakeVisible(status); addAndMakeVisible(surface); for(auto* b:{&audition,&save,&load,&exportWav}) addAndMakeVisible(b); audition.onClick=[this]{engine.strike(engine.parameters.velocity.load(),engine.parameters.position.load());}; auto dir=juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("CymbalForge"); dir.createDirectory(); save.onClick=[this,dir]{auto f=dir.getChildFile("preset.json"); status.setText(PresetManager::save(f,engine.parameters)?"Saved Documents/CymbalForge/preset.json":"Preset save failed",juce::dontSendNotification);}; load.onClick=[this,dir]{auto f=dir.getChildFile("preset.json"); status.setText(PresetManager::load(f,engine.parameters)?"Preset loaded":"No valid preset found",juce::dontSendNotification);}; exportWav.onClick=[this,dir]{auto f=dir.getChildFile("cymbal-hit.wav"); status.setText(OfflineRenderer::renderWav(f,engine.parameters)?"Exported Documents/CymbalForge/cymbal-hit.wav":"WAV export failed",juce::dontSendNotification);}; const char* names[]={"Velocity","Brightness","Decay","Noise","Reverb","Gain"}; std::atomic<float>* values[]={&e.parameters.velocity,&e.parameters.brightness,&e.parameters.decay,&e.parameters.noise,&e.parameters.reverb,&e.parameters.gain}; for(int i=0;i<6;++i){ auto* s=sliders.add(new juce::Slider(names[i])); s->setRange(0,1,.001); s->setValue(values[i]->load()); s->setTextBoxStyle(juce::Slider::TextBoxBelow,false,64,20); s->onValueChange=[s,v=values[i]]{v->store((float)s->getValue());}; addAndMakeVisible(s); } } void MainEditor::resized(){auto b=getLocalBounds().reduced(14); auto header=b.removeFromTop(30); title.setBounds(header.removeFromLeft(430)); status.setBounds(header); auto actions=b.removeFromTop(34); for(auto* x:{&audition,&save,&load,&exportWav}) x->setBounds(actions.removeFromLeft(120).reduced(3)); auto controls=b.removeFromBottom(150); surface.setBounds(b); auto w=controls.getWidth()/6; for(int i=0;i<sliders.size();++i) sliders[i]->setBounds(controls.removeFromLeft(w).reduced(4));} }
